contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint newMin, address newLog) public payable {
        // Ensure we don't overflow when computing newMinPlus: keep within uint range
        uint newMinPlus = newMin == type(uint).max ? newMin : newMin + 1;

        // Initial configuration calls are allowed before Initialized()
        c.SetMinSum(newMin); if (__ESBMC_reverted()) return;
        c.SetLogFile(newLog); if (__ESBMC_reverted()) return;

        // Flip the initialized flag
        c.Initialized(); if (__ESBMC_reverted()) return;

        // Now attempts to change MinSum or Log should revert. Capture revert flags.
        bool setMinReverted;
        bool setLogReverted;

        c.SetMinSum(newMinPlus); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setMinReverted = true;
        } else {
            setMinReverted = false;
        }

        c.SetLogFile(newLog); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            setLogReverted = true;
        } else {
            setLogReverted = false;
        }

        // Assert the general property: after Initialized(), both setter calls revert.
        assert(setMinReverted && setLogReverted);
    }

    receive() external payable {}
}

